import dash
import dash\_core\_components as dcc
import dash\_html\_components as html
import pandas as pd

app = dash.Dash()

# define callback function
def update\_chart(n\_interval):
 # fetch updated stock data
 df = pd.read\_csv('stock\_data.csv')

 # update chart with new data
 chart = dcc.Graph(id='stock-chart', figure={
 'data': [{
 'x': df['date'],
 'y': df['price'],
 'type': 'line'
 }]
 })

 return chart

app.layout = html.Div([
 dcc.Interval(
 id='chart-update-interval',
 interval=1\*1000, # in milliseconds
 n\_intervals=0
 ),
 html.Div(id='chart-container')
])

# specify the callback function
@app.callback(
 dash.dependencies.Output('chart-container', 'children'),
 [dash.dependencies.Input('chart-update-interval', 'n\_intervals')]
)
def update\_chart\_display(n\_intervals):
 return update\_chart(n\_intervals)

if \_\_name\_\_ == '\_\_main\_\_':
 app.run\_server()

